import json
import re
from docx import Document


def replace_placeholders_in_paragraph(paragraph, replacements):
    """Replace {{PLACEHOLDER}} patterns across runs in a paragraph,
    handling cases where placeholders are split across multiple runs."""
    # Build full text and a map of (run_index, char_offset_in_run) for each char
    full_text = ""
    char_map = []
    for ri, run in enumerate(paragraph.runs):
        for ci, ch in enumerate(run.text):
            char_map.append((ri, ci))
        full_text += run.text

    if not full_text:
        return

    # Find all placeholder occurrences
    pattern = re.compile(r"\{\{(\w+)\}\}")
    matches = list(pattern.finditer(full_text))
    if not matches:
        return

    # Process matches in reverse order so positions remain valid
    for match in reversed(matches):
        key = match.group(1)
        if key not in replacements:
            continue

        start = match.start()
        end = match.end()
        replacement_value = str(replacements[key])

        start_run, start_offset = char_map[start]
        end_run, end_offset = char_map[end - 1]

        runs = paragraph.runs
        if start_run == end_run:
            run = runs[start_run]
            run.text = run.text[:start_offset] + replacement_value + run.text[end_offset + 1:]
        else:
            runs[start_run].text = runs[start_run].text[:start_offset] + replacement_value
            for ri in range(start_run + 1, end_run):
                runs[ri].text = ""
            runs[end_run].text = runs[end_run].text[end_offset + 1:]


def handle_conditional_in_paragraph(paragraph, condition_met):
    """Handle {{IF_RELOCATION}}...{{END_IF_RELOCATION}} within a single paragraph.

    If condition_met: remove the IF/END_IF markers, keep the content.
    If not condition_met: remove the markers and everything between them.
    """
    full_text = "".join(run.text for run in paragraph.runs)

    if "{{IF_RELOCATION}}" not in full_text:
        return

    if condition_met:
        # Remove only the markers, keep content between them
        new_text = full_text.replace("{{IF_RELOCATION}}", "").replace("{{END_IF_RELOCATION}}", "")
    else:
        # Remove markers and content between them
        new_text = re.sub(
            r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}',
            '', full_text, flags=re.DOTALL
        )

    # Rewrite: put all text in first run, clear the rest
    if paragraph.runs:
        paragraph.runs[0].text = new_text
        for run in paragraph.runs[1:]:
            run.text = ""


def replace_in_all_paragraphs(doc, replacements):
    """Replace placeholders in all paragraphs including those in table cells."""
    for para in doc.paragraphs:
        replace_placeholders_in_paragraph(para, replacements)

    def process_tables(tables):
        for table in tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        replace_placeholders_in_paragraph(para, replacements)
                    process_tables(cell.tables)

    process_tables(doc.tables)


def main():
    # Load employee data
    with open('/root/employee_data.json', 'r') as f:
        data = json.load(f)

    # Open template
    doc = Document('/root/offer_letter_template.docx')

    # Step 1: Handle conditional section
    relocation = data.get("RELOCATION_PACKAGE", "No") == "Yes"
    for para in doc.paragraphs:
        handle_conditional_in_paragraph(para, relocation)

    # Step 2: Replace all placeholders
    replace_in_all_paragraphs(doc, data)

    # Save result
    doc.save('/root/offer_letter_filled.docx')
    print("Offer letter saved to /root/offer_letter_filled.docx")


if __name__ == "__main__":
    main()

